def load_config(raw):
    # Current implementation only understands the legacy flat shape.
    result = dict(raw)
    service = {}
    if 'endpoint' in result:
        service['endpoint'] = result.pop('endpoint')
    if 'token' in result:
        service['token'] = result.pop('token')
    result['service'] = service
    return result

